/* data/maulid/adl.js - Maulid Adl-Dliya'ul Lami' (Arab, transliterasi, terjemah). Dibuat oleh template-kitab/maulid_dari_md.py.
   Satu bait = {no, ar, lt, id}. Boleh diedit langsung. */
registerMaulid({"id": "adl", "judul": "Maulid Adl-Dliya'ul Lami'", "sumber": "Adl-Dliyâ'ul-Lâmi' bidzikri Maulidin-Nabiyyisy-Syâfi'i",bagian:[
{judul:"Pembuka: Ya Rabbi Shalli 'ala Muhammad",isi:[
{"ar": "يَا رَبِّ صَلِّ عَلَى مُحَمَّدْ ۞ حَبِيْبِكَ الشَّافِعِ الْمُشَفَّعْ", "lt": "Yâ rabbi shalli ‘alâ Muḥammad ۞ ḥabîbikasy-syâfi‘il-musyaffa‘", "id": "Ya Rabb limpahkanlah rahmat atas Nabi Muhammad ﷺ, Kekasih-Mu pemberi syafaat yang diharapkan syafaatnya.", "no": 1},
{"ar": "يَا رَبِّ صَلِّ عَلَى مُحَمَّدْ ۞ أَغْلَى الْوَرَى رُتْبَةً وَأَرْفَعْ", "lt": "Yâ rabbi shalli ‘alâ Muḥammad ۞ a‘lal-warâ rutbatan wa arfa‘", "id": "Ya Rabb limpahkanlah rahmat atas Nabi Muhammad ﷺ, Manusia yang teramat sangat luhur derajatnya.", "no": 2},
{"ar": "يَا رَبِّ صَلِّ عَلَى مُحَمَّدْ ۞ أَسْمَى الْبَرَايَا جَاهًا وَأَوْسَعْ", "lt": "Yâ rabbi shalli ‘alâ Muḥammad ۞ asmal-barâyâ jâhan wa ausa‘", "id": "Ya Rabb limpahkanlah rahmat atas Nabi Muhammad ﷺ, Makhluk yang sangat tinggi dan luas kedudukannya.", "no": 3},
{"ar": "يَا رَبِّ صَلِّ عَلَى مُحَمَّدْ ۞ وَاسْلُكْ بِنَا رَبِّ خَيْرَ مَهْيَعْ", "lt": "Yâ rabbi shalli ‘alâ Muḥammad ۞ wasluk binâ rabbi khaira mahya‘", "id": "Ya Rabb limpahkanlah rahmat atas Nabi Muhammad ﷺ, Wahai Tuhan, bimbinglah kami ke jalan yang terbaik.", "no": 4},
{"ar": "يَا رَبِّ صَلِّ عَلَى مُحَمَّدْ ۞ وَعَافِنَا وَاشْفِ كُلَّ مُوْجَعْ", "lt": "Yâ rabbi shalli ‘alâ Muḥammad ۞ wa ‘âfinâ wasyfi kulla mûja‘", "id": "Ya Rabb limpahkanlah rahmat atas Nabi Muhammad ﷺ, Sembuhkanlah kami dari segala derita penyakit.", "no": 5},
{"ar": "يَا رَبِّ صَلِّ عَلَى مُحَمَّدْ ۞ وَأَصْلِحِ الْقَلْبَ وَاعْفُ وَانْفَعْ", "lt": "Yâ rabbi shalli ‘alâ Muḥammad ۞ wa ashlihil-qalba wa‘fu wanfa‘", "id": "Ya Rabb limpahkanlah rahmat atas Nabi Muhammad ﷺ, Perbaikilah hati, ampunilah, dan berilah kami (segala yang) manfaat.", "no": 6},
{"ar": "يَا رَبِّ صَلِّ عَلَى مُحَمَّدْ ۞ وَاكْفِ الْمُعَادِيْ وَاصْرِفْهُ وَازْدَغْ", "lt": "Yâ rabbi shalli ‘alâ Muḥammad ۞ wakfil-mu‘âdi washrifhu warda'", "id": "Ya Rabb limpahkanlah rahmat atas Nabi Muhammad ﷺ, Bentengilah dan hindarkanlah kami dari musuh-musuh yang datang pada kami.", "no": 7},
{"ar": "يَا رَبِّ صَلِّ عَلَى مُحَمَّدْ ۞ نَحِلُّ فِيْ حِصْنِكَ الْمُمَنَّعْ", "lt": "Yâ rabbi shalli ‘alâ Muḥammad ۞ naḥillu fî ḥishnikal-mumanna‘", "id": "Ya Rabb limpahkanlah rahmat atas Nabi Muhammad ﷺ, Kami singgah di dalam Benteng-Mu yang melindungi (dari berbagai macam gangguan).", "no": 8},
{"ar": "يَا رَبِّ صَلِّ عَلَى مُحَمَّدْ ۞ رَبِّ ارْضَ عَنَّا رِضَاكَ الْأَرْفَعْ", "lt": "Yâ rabbi shalli ‘alâ Muḥammad ۞ rabbir-dlâ ‘annâ ridlâkal-arfa‘", "id": "Ya Rabb limpahkanlah rahmat atas Nabi Muhammad ﷺ, Ya Allah ridhailah kami dengan keridhaan-Mu yang agung.", "no": 9},
{"ar": "يَا رَبِّ صَلِّ عَلَى مُحَمَّدْ ۞ وَاجْعَلْ لَنَا فِي الْجِنَانِ مَجْمَعْ", "lt": "Yâ rabbi shalli ‘alâ Muḥammad ۞ waj‘al lanâ fil-jinâni majma‘", "id": "Ya Rabb limpahkanlah rahmat atas Nabi Muhammad ﷺ, Jadikanlah kami sebagai orang-orang yang akan berkumpul dengan nabi-Mu di surga.", "no": 10},
{"ar": "يَا رَبِّ صَلِّ عَلَى مُحَمَّدْ ۞ رَافِقْ بِنَا خَيْرَ خَلْقِكَ اجْمَعْ", "lt": "Yâ rabbi shalli ‘alâ Muḥammad ۞ râfiq binâ khaira khalqikaj-ma‘", "id": "Ya Rabb limpahkanlah rahmat atas Nabi Muhammad ﷺ, Jadikanlah kami selalu bersama-sama dengan sebaik-baik ciptaan-Mu (Nabi Muhammad ﷺ).", "no": 11},
{"ar": "يَا رَبِّ صَلِّ عَلَى مُحَمَّدْ ۞ يَا رَبِّ صَلِّ عَلَيْهِ وَسَلِّمْ", "lt": "Yâ rabbi shalli ‘alâ Muḥammad ۞ yâ rabbi shalli ‘alaihi wa sallim", "id": "Ya Rabb limpahkanlah rahmat atas Nabi Muhammad ﷺ, Ya Allah limpahkanlah rahmat dan keselamatan kepada beliau ﷺ.", "no": 12},
{"ar": "اللَّهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ وَعَلَى آلِهِ", "lt": "{Allâhumma shalli wa sallim wa bârik ‘alaihi wa ‘ala âlihi}", "id": "Ya Allah limpahkanlah rahmat keagungan, keselamatan, serta keberkahan kepada Nabi dan keluarganya.", "no": 13}]},
{judul:"Inna Fatahna",isi:[
{"ar": "أَعُوْذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيْمِ", "lt": "A‘ûdzu billâhi minasy-syaithânir-rajîmi", "id": "Aku berlindung kepada Allah dari godaan setan yang terkutuk.", "no": 1},
{"ar": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "lt": "Bismillâhirrahmânir-rahîmi", "id": "Dengan nama Allah Yang Maha Pengasih lagi Maha Penyayang.", "no": 2},
{"ar": "إِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِينًا لِّيَغْفِرَ لَكَ اللَّهُ مَا تَقَدَّمَ مِن ذَنبِكَ وَمَا تَأَخَّرَ وَيُتِمَّ نِعْمَتَهُ عَلَيْكَ وَيَهْدِيَكَ صِرَاطًا مُّسْتَقِيمًا وَيَنصُرَكَ اللَّهُ نَصْرًا عَزِيزًا", "lt": "Innâ fataḥnâ laka fatḥam mubîna. liyaghfira lakallâhu mâ taqaddama min dzanbika wa mâ ta'akhkhara wa yutimma ni‘matahu ‘alaika wa yahdîyaka shirâthan mustaqîman, wa yansurakallâhu nashran ‘azîzan", "id": "Sungguh Kami telah menganugerahkan kepadamu kemenangan yang nyata, agar Allah memberikan ampunan kepadamu (Nabi Muhammad) atas dosamu yang lalu dan yang akan datang, menyempurnakan nikmat-Nya atasmu, menunjukimu ke jalan yang lurus, dan agar Allah menolongmu dengan pertolongan yang besar.", "no": 3},
{"ar": "لَقَدْ جَاءَكُمْ رَسُولٌ مِّنْ أَنفُسِكُمْ عَزِيزٌ عَلَيْهِ مَا عَنِتُّمْ حَرِيصٌ عَلَيْكُم بِالْمُؤْمِنِينَ رَءُوفٌ رَّحِيمٌ فَإِن تَوَلَّوْا فَقُلْ حَسْبِيَ اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ", "lt": "Laqad jâ'akum rasûlun min anfusikum ‘azîzun ‘alaihi mâ ‘anittum ḥarîshun ‘alaikum bil-mu'minîna ra'ûfun raḥîm. fa in tawallau faqul ḥasbiyallâhu lâ ilâha illâ huwa ‘alaihi tawakkaltu wa huwa rabbul-‘arsyil ‘adhîm", "id": "Sungguh, benar-benar telah datang kepadamu seorang rasul dari kaummu sendiri. Berat terasa olehnya penderitaan yang kamu alami, sangat menginginkan (keimanan dan keselamatan) bagimu, dan (bersikap) penyantun dan penyayang terhadap orang-orang mukmin. Jika mereka berpaling (dari keimanan), katakanlah (Nabi Muhammad), “Cukuplah Allah bagiku. Tidak ada tuhan selain Dia. Hanya kepada-Nya aku bertawakal dan Dia adalah Tuhan pemilik ‘Arsy (singgasana) yang agung.”", "no": 4},
{"ar": "إِنَّ اللَّهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ ۚ يَا أَيُّهَا الَّذِينَ آمَنُوا صَلَّوْا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا", "lt": "Innallâha wa malâ'ikatahu yushallûna ‘alan-nabî, yâ ayyuhal-ladzîna âmanû shallû ‘alaihi wa sallimû taslîmâ", "id": "Sesungguhnya Allah dan para malaikat-Nya berselawat untuk Nabi. Wahai orang-orang yang beriman, berselawatlah kamu untuk Nabi dan ucapkanlah salam dengan penuh penghormatan kepadanya.", "no": 5},
{"ar": "اللَّهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ وَعَلَى آلِهِ", "lt": "{Allâhumma shalli wa sallim wa bârik ‘alaihi wa ‘ala âlihi}", "id": "Ya Allah limpahkanlah rahmat keagungan, keselamatan, serta keberkahan kepada Nabi dan keluarganya.", "no": 6}]},
{judul:"Bagian I: Alhamdulillahil ladzi…",isi:[
{"ar": "الْحَمْدُ لِلَّهِ الَّذِي هَدَانَا ۞ بِعَبْدِهِ الْمُخْتَارِ مَنْ دَعَانَا", "lt": "Al-ḥamdulillâhil-ladzî hadânâ ۞ bi‘abdihil-mukhtâri man da‘ânâ", "id": "Segala puji hanyalah untuk Allah yang telah memberi kita petunjuk. Melalui Hamba-Nya yang telah terpilih ﷺ yang telah menyeru kami.", "no": 1},
{"ar": "إِلَيْهِ بِالْإِذْنِ وَقَدْ نَادَانَا ۞ لَبَّيْكَ يَا مَنْ دَلَّنَا وَهَدَانَا", "lt": "Ilaihi bil-idzni wa qad nâdânâ ۞ labbaika yâ man dallanâ wa ḥadânâ", "id": "Kepada-Nya dengan izin-Nya, dan sungguh Beliau ﷺ telah menyeru kami. Kami memenuhi panggilanmu, wahai Nabi ﷺ yang telah menyampaikan petunjuk dan motivasi kepada kami.", "no": 2},
{"ar": "صَلَّى عَلَيْكَ اللَّهُ بَارِئُكَ الَّذِي ۞ بِكَ يَا مُشَفَّعُ خَصَّنَا وَحَبَانَا", "lt": "Shallâ ‘alaikallâhu bâri'ukal-ladzî ۞ bika yâ musyaffa‘u khashshanâ wa ḥabânâ", "id": "Semoga Allah melimpahkan rahmat kepadamu yang telah menciptakanmu. Wahai yang diharapkan syafaatnya, sebab engkau kami spesial dan terberkahi.", "no": 3},
{"ar": "مَعَ آلِكَ الْأَطْهَارِ مَعْدِنِ سِرِّكَ ۞ الْأَسْمَى فَهُمْ سُفُنُ النَّجَاةِ حِمَانَا", "lt": "Ma‘ âlikal-athhâri ma‘dini sirrika ۞ al-asmâ fahum sufunun-najâti ḥimânâ", "id": "(Semoga Allah melimpahkan rahmat) juga kepada para keluargamu yang suci sebagai sumber-sumber rahasiamu yang mulia, merekalah kapal-kapal penyelamat yang melindungi kami.", "no": 4},
{"ar": "وَعَلَى صَحَابَتِكَ الْكِرَامِ حُمَاةِ دِيْ ۞ نِكَ أَصْبَحُوا لِوَائِهِ عُنْوَانَا", "lt": "Wa ‘alâ shahâbatikal-kirâmi ḥumâti dî- ۞ nika ashbaḥû liwâ'ihi ‘unwânâ", "id": "(Semoga Allah melimpahkan rahmat) pula kepada para sahabatmu yang mulia, yang menjadi pembela ajaranmu, dan menjadi contoh panutan bagi pecinta-Nya ﷺ.", "no": 5},
{"ar": "وَالتَّابِعِيْنَ لَهُمْ بِصِدْقٍ مَا حَدَى ۞ حَادِيْ الْمَوَدَّةِ هَيَّجَ الْأَشْجَانَا", "lt": "Wat-tâbi‘îna lahum bishidqin mâ ḥadâ ۞ ḥâdil-mawwadati hayyajal-asyjânâ", "id": "(Semoga Allah melimpahkan rahmat) juga kepada para tabi'in, yang mengikuti mereka dengan benar, sebesar senandung rasa cinta yang mengguncang kesedihan.", "no": 6},
{"ar": "وَاللَّهِ مَا ذُكِرَ الْحَبِيْبُ لَدَى الْمُحِبِّ ۞ إِلَّا وَأَضْحَى وَإِلْهَا نَشْوَانَا", "lt": "Wallâhi mâ dzukiral-ḥabîbu ladal-muḥibbi ۞ illâ wa adlḥâ wa ilâhan nasywânâ", "id": "Demi Allah tidaklah disebutkan nama sang kekasih ﷺ pada orang yang mencintainya, kecuali dia akan terhenyak dan dimabuk rindu kepadanya (Rasulullah ﷺ).", "no": 7},
{"ar": "أَيْنَ الْمُحِبُّوْنَ الَّذِينَ عَلَيْهُمُ ۞ بَذْلُ النُّفُوْسِ مَعَ النَفَائِسِ هَانَا", "lt": "Ainal-muḥibbûnal-ladzîna ‘alaihimu ۞ badzlun-nufûsi ma‘an-nafâ'isi hânâ", "id": "Di manakah mereka para pecinta, yang rela mengorbankan jiwa raga serta harta bendanya yang hina itu?", "no": 8},
{"ar": "لَا يَسْمَعُوْنَ بِذِكْرِ طَهَ الْمُصْطَفَى ۞ إِلَّا بِهِ انْتَعَشُوْا وَأَذْهَبَ رَانَا", "lt": "Lâ yasma‘ûna bidzikri thahal-mushthafâ ۞ illâ bihin-ta‘asyû wa adzhaba rânâ", "id": "Tidaklah mereka mendengar sebutan Thâhâ al-Musthafa ﷺ, kecuali bangkitlah kembali semangatnya dan lenyaplah segala kesedihannya.", "no": 9},
{"ar": "فَهْتَاجَتِ الْأَرْوَاحُ تَسْتَاقُ اللِّقَا ۞ وَتَحِنُّ تَسْأَلُ رَبَّهَا الرِّضْوَانَا", "lt": "Fahtâjâtil-arwâhu tasytâqul-liqâ ۞ wa taḥinnu tas'alu rabbahar-ridlwânâ", "id": "Bergoncanglah jiwa karena rasa rindu ingin segera berjumpa dan merintih memohon ridha kepada Tuhan-Nya.", "no": 10},
{"ar": "حَالَ الْمُحِبِّينَ كَذَا فَاسْمَعْ إِلَى ۞ سِيَرِ الْمُشَفَّعِ وَازْهُفِ الْأَذَانَا", "lt": "Ḥâlal-muḥibbîna kadzâ fasma‘ ilâ ۞ siyaril-musyaffa‘i warhif-âdzânâ", "id": "Begitulah keadaan para pecinta (Rasul ﷺ) maka dengarkanlah kisah perjalanan hidup al-Musyaffa‘ ﷺ (nabi yang diharapkan syafaatnya) dan tajamkan telinga dengan saksama.", "no": 11},
{"ar": "وَانْصَتْ إِلَى أَوْصَافِ طَهَ الْمُجْتَبَى ۞ وَاحْضِرْ لَقَلْبَكَ يَمْتَلِئْ وِجْدَانَا", "lt": "Wanshit ila aushâfi thahal-mujtabâ ۞ Waḥdlir liqalbika yamtaliî wijdânâ", "id": "Simaklah dengan teliti sifat-sifat Thâhâ al-Mujtaba ﷺ (sang pilihan), dan hadirkanlah hatimu, niscaya hatimu akan dipenuhi dengan kerinduan.", "no": 12},
{"ar": "يَا رَبَّنَا صَلِّ وَسَلِّمْ دَائِمًا ۞ عَلَى حَبِيْبِكَ مَنْ إِلَيْكَ دَعَانَا", "lt": "Yâ rabbi wasallim da‘îman ۞ ‘alâ ḥabîbika man ilaika da‘ânâ", "id": "Wahai Tuhan kami, limpahkanlah rahmat dan keselamatan selamanya, pada kekasih-Mu yang telah menyeru kami kepada-Mu.", "no": 13},
{"ar": "اللَّهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ وَعَلَى آلِهِ", "lt": "{Allâhumma shalli wa sallim wa bârik ‘alaihi wa ‘ala âlihi}", "id": "Ya Allah limpahkanlah rahmat keagungan, keselamatan, serta keberkahan kepada Nabi dan keluarganya.", "no": 14}]},
{judul:"Bagian II: Nabba'anallahu…",isi:[
{"ar": "نَبَّأَنَا اللَّهُ فَقَالَ جَاءَكُمْ ۞ نُورٌ فَسُبْحَانَ الَّذِي أَنْبَانَا", "lt": "Nabba’anallâhu faqâla jâ’akum ۞ nûrun fasubḥânal-ladzî anbânâ", "id": "Allah telah memberi kabar kepada kita dengan firman-Nya: “Telah datang kepada kalian An-Nur (cahaya). Mahasuci Allah yang telah memberi kita kabar ini.”", "no": 1},
{"ar": "وَالنُّورُ طَهَ عَبْدُهُ مَنَّ بِهِ ۞ فِي ذِكْرِهِ أَعْظَمُ بِهِ مَنَّانَا", "lt": "Wan-nûru thaha ‘abduhu manna bihi ۞ fî dzikrihi a‘dhim bihi mannânâ", "id": "Cahaya Thâhâ ﷺ hamba-Nya membuat kita dilimpahi karunia ketika menyebutnya. Agungkanlah karunia kami berkat menyebut Nabi Muhammad ﷺ.", "no": 2},
{"ar": "هُوَ رَحْمَةُ الْمَوْلَى تَأَمَّلْ قَوْلَهُ ۞ فَلْيَفْرَحُوا وَاغْدُ بِهِ فَرْحَانَا", "lt": "Huwa raḥmatul-maulâ ta’ammal qaulahu ۞ falyafraḥû waghdu bihi farḥânâ", "id": "Beliau ﷺ merupakan suatu rahmat dari sang pencipta, maka perhatikanlah Firman-Nya: “Maka bergembiralah kamu”, maka datanglah kebahagiaan kita berkat beliau ﷺ.", "no": 3},
{"ar": "مُسْتَمْسِكًا بِالْعُرْوَةِ الْوُثْقَى وَمُعْ ۞ تَصِمًا بِحَبْلِ اللَّهِ مَنْ أَنْسَانَا", "lt": "Mustamsikan bil-‘urwatil-wutsqâ wa mu‘-tashiman biḥablillâhi man ansyânâ", "id": "Dengan senantiasa berpegangan pada tali yang kuat (Al-Qur’an dan Al-Hadits) dan dengan berpegang teguh pada tali Allah yang menciptakan kita.", "no": 4},
{"ar": "وَاسْتَشْعِرَنْ أَنْوَارَ مَنْ قِيلَ مَتَى ۞ كُنْتَ نَبِيًّا قَالَ آدَمُ كَانَا", "lt": "Wastasy‘iran anwâra man qîla matâ ۞ kunta nabiyyan qâla âdamu kânâ", "id": "Rasakanlah akan kehadiran cahaya-cahaya Rasulullah ﷺ yang ketika dikatakan: “Sejak kapankah Engkau diangkat sebagai nabi?” Beliau menjawab, “Kenabianku semenjak Adam as.”", "no": 5},
{"ar": "بَيْنَ التُّرَابِ وَبَيْنَ مَاءٍ فَاسْتَفِقْ ۞ مِنْ غَفْلَةٍ عَنْ ذَا وَكُنْ يَقْظَانَا", "lt": "Bainat-turâbi wa baina mâ’in fastafiq ۞ min ghaflatin ‘an dzâ wa kun yaqdhânâ", "id": "Masih berupa antara air dan tanah, sadarilah olehmu dari kelalaian-kelalaianmu itu dan terjagalah.", "no": 6},
{"ar": "وَاعْبُرْ إِلَى أَسْرَارِ رَبِّي لَمْ يَزَلْ ۞ يَنْقُلُنِي بَيْنَ الْخِيَارِ مُصَانَا", "lt": "Wa‘bur ilâ asrâri rabbi lam yazal ۞ yanqulunî bainal-khiyâri mushânâ", "id": "Maka pahamilah rahasia-rahasia Tuhanku yang selalu memindahkanku ﷺ di antara sulbi orang-orang yang terpilih serta terjaga kesuciannya.", "no": 7},
{"ar": "لَمْ تَفْتَرِقْ مِنْ شُعْبَتَيْنِ إِلَّا أَنَا ۞ فِي خَيْرِهَا حَتَّى بُرُزِيَ ِآنَا", "lt": "Lam taftariq min syu‘bataini illâ anâ ۞ fî khairihâ ḥattâ buruziya ânâ", "id": "Tidaklah terpisah dari dua kelompok (suku), kecuali aku berada pada yang terbaik, begitulah hingga terlahirnya diriku.", "no": 8},
{"ar": "فَأَنَا خِيَارٌ مِنْ خِيَارٍ قَدْ خَرَجْتُ ۞ مِنْ نِكَاحٍ لِي إِلَيهَا شَانَا", "lt": "Fa’anâ khiyârun min khiyârin qad kharajtu ۞ min nikâḥin lî ilâhiya sânâ", "id": "Aku adalah yang terpilih dari semua yang terpilih, dan aku terlahir dari pernikahan yang Tuhanku telah menjaganya.", "no": 9},
{"ar": "طَهَّرَهُ اللَّهُ حَمَاهُ اخْتَارَهُ ۞ وَمَا بَرَى كَمِثْلِهِ إِنْسَانَا", "lt": "Thahharahul-lâhu ḥamâhukhtârahu ۞ wa mâ barâ kamitslihi insânâ", "id": "Allah telah menyucikannya ﷺ, serta melindungi dan memilihnya ﷺ. Tidaklah pernah Allah menciptakannya manusia menyerupainya ﷺ.", "no": 10},
{"ar": "وَبِحُبِّهِ وَبِذِكْرِهِ وَالنَّصْرِ وَالْتَّ ۞ وْقِيرِ رَبُّ الْعَرْشِ قَدْ أَوْصَانَا", "lt": "Wa biḥubbihi wa bidzikrihi wan-nashri wat-tauqîra rabbul-‘arsyi qad aushânâ", "id": "Dan dengan mencintai dan mengingat serta membantu syari’atnya, dan dengan penghormatan padanya ﷺ Allah Pencipta Arsy telah mewasiatkan kita.", "no": 11},
{"ar": "يَا رَبَّنَا صَلِّ وَسَلِّمْ دَائِمًا ۞ عَلَى حَبِيْبِكَ مَنْ إِلَيْكَ دَعَانَا", "lt": "Yâ rabbanâ shalli wa sallim da’iman ۞ ‘alâ ḥabîbika man ilaika da’ânâ", "id": "Wahai Tuhan kami, limpahkanlah rahmat dan keselamatan selamanya, pada kekasih-Mu yang telah menyeru kami kepada-Mu.", "no": 12},
{"ar": "اللَّهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ وَعَلَى آلِهِ", "lt": "{Allâhumma shalli wa sallim wa bârik ‘alaihi wa ‘ala âlihi}", "id": "Ya Allah limpahkanlah rahmat keagungan, keselamatan, serta keberkahan kepada Nabi dan keluarganya.", "no": 13}]},
{judul:"Bagian III: Hadza wa qad nasyara…",isi:[
{"ar": "هَذَا وَقَدْ نَشَرَ الْإِلَهُ نُعُوتَهُ ۞ فِي الْكُتُبِ بَيَّنَهَا لَنَا تِبْيَانَا", "lt": "Hâdzâ wa qad nasyaral-ilâhu nu‘ûtahu ۞ fil-kutbi bayyanahâ lanâ tibyânâ", "id": "Begitulah, Tuhan telah menyebarkan tentang sifat-sifatnya ﷺ dalam kitab-kitab (terdahulu) yang menjelaskannya dengan sangat terang.", "no": 1},
{"ar": "أَخَذَ مِيثَاقَ النَّبِيِّينَ لَمَا ۞ آتَيْتُكُمْ مِنْ حِكْمَةٍ إِحْسَانَا", "lt": "Akhadza mîtsâqan-nabiyyîna lamâ ۞ âtaitukum min ḫikmatin iḫsânâ", "id": "Dia (Allah) telah mengambil perjanjian dari para nabi ketika telah kudatangan pada kalian hikmah dan kemuliaan.", "no": 2},
{"ar": "وَجَاءَكُمْ رَسُولُنَا لَتُؤْمِنُنَّ ۞ وَتَنْصُرُونَ وَتُصْبِحُونَ أَعْوَانَا", "lt": "Wa jâ’akum rasûlunâ latu’minunna ۞ wa tanshurûna wa tushbiḥûna a‘wânâ", "id": "Teladah datang utusan kami (Rasulullah ﷺ) pada kalian (wahai para nabi) maka agar kalian (wahai para nabi) beriman padanya, dan kalian (wahai para nabi) mendukungnya ﷺ, dan agar kalian (wahai para nabi) menjadi pengikutnya.", "no": 3},
{"ar": "قَدْ بَشَّرُوا أَقْوَامَهُمْ بِالْمُصْطَفَى ۞ أَعْظَمْ بِذَلِكَ رُتْبَةً وَمَكَانَا", "lt": "Qad basysyarû aqwâmahum bil-mushthafâ ۞ a‘dhim bidzâlika rutbatan wa makânâ", "id": "Para nabi terdahulu telah memberi kabar gembira pada kaum mereka akan kedatangan nabi terpilih, maka muliakanlah martabat dan kedudukkannya.", "no": 4},
{"ar": "فَهُوَ وَإِنْ جَاءَ الْأَخِيرُ مُقَدَّمُ ۞ يَمْشُونَ تَحْتَ لِوَاءِ مَنْ نَادَانَا", "lt": "Fahuwa wa in jâ’al-akhîru muqaddamun ۞ yamsyûna taḥta liwâ’i man nâdânâ", "id": "Apabila telah datang hari kiamat, para nabi terdahulu berjalan di bawah naungan panji sang nabi ﷺ yang telah menyeru kita.", "no": 5},
{"ar": "يَا أُمَّةَ الْإِسْلَامِ أَوَّلُ شَافِعٍ ۞ وَمُشَفَّعٍ أَنَا قَطُّ لَا أَتَوانَى", "lt": "Yâ ummatal-islâmi awwalu syâfi‘in ۞ wa musyaffa‘in anâ qaththu lâ atawânâ", "id": "Wahai umat Islam, aku adalah yang pertama memberi syafaat dan diharapkan syafaatnya, dan tidaklah sama sekali aku memperlambat (syafaat itu).", "no": 6},
{"ar": "حَتَّى أُنَادَى ازْفَعْ وَسَلْ تُعْطَ وَقُلْ ۞ يُسْمَعْ لِقَوْلِكَ نَجْمُ فَخْرِكَ بَانَا", "lt": "Ḥattâ unâdâr-fa‘ was al tu‘tha wa qul ۞ yusma‘ liqaulika najmu fakhrik bânâ", "id": "Hingga diserukan kepadaku (ketika bersujud memohon syafaat), “Angkatlah kepalamu (wahai Muhammad ﷺ), katakanlah permintaanmu, niscaya engkau diberi; bicaralah, niscaya engkau didengar.” Bintang kemuliaanmu (wahai Nabi ﷺ) sungguh jelas dan terang.", "no": 7},
{"ar": "وَلِوَاءُ حَمْدِ اللَّهِ جَلَّ بِيَدِي ۞ وَلَأَوَّلًا آتِي أَنَا الْجِنَانَا", "lt": "Wa liwâ’u ḫamdillâhi jalla biyadî ۞ wa la’awwalan âtî anal-jinânâ", "id": "Panji pujian kepada Allah yang Mahaperkasa berada di tanganku ﷺ dan aku ﷺ adalah manusia pertama yang mendatangi surga.", "no": 8},
{"ar": "وَأَكْرَمُ الْخَلْقِ عَلَى اللَّهِ أَنَا ۞ فَلَقَدْ حَبَاكَ اللَّهُ مِنْهُ حَنَانَا", "lt": "Wa akramul-khalqi ‘alallâhi anâ ۞ falaqad ḫabbâkallâhu minhu ḫanânâ", "id": "Aku ﷺ telah menjadi ciptaan yang paling mulia di sisi Allah. Sungguh engkau (wahai Nabi ﷺ) telah terpelihara oleh Allah dengan kasih sayang-Nya.", "no": 9},
{"ar": "وَلَسَوْفَ يُعْطِيكَ فَتَرْضَى جَلَّ مِنْ ۞ مُعْطٍ تَقَاصَرَ عَنْ عَطَاهُ نُهَانَا", "lt": "Wa lasaufa yu‘thîka fatardlâ jalla min ۞ mu‘thin taqâshara ‘an ‘athâhu nuhânâ", "id": "“Dan kelak Dia pasti memberikan karunia-Nya kepadamu, hingga engkau puas.” (Ayat ini) merupakan tanda kebesaran Sang Maha Pemberi, yang sukar dijangkau akal.", "no": 10},
{"ar": "بِاللَّهِ كَرِّرْ ذِكْرَ وَصْفِ مُحَمَّدٍ ۞ كَيْمَا تُزِيحَ عَنِ الْقُلُوبِ الرَّانَا", "lt": "Billâhi karrir dzikra washfi muḫammadin ۞ kaimâ tuzîḫa ‘anil-qulûbir-rânâ", "id": "Demi Allah, ingat-ingatlah sifat Nabi Muhammad ﷺ berulang-ulang, agar menyingkirkan kotoran-kotoran dari hati.", "no": 11},
{"ar": "يَا رَبَّنَا صَلِّ وَسَلِّمْ دَائِمًا ۞ عَلَى حَبِيْبِكَ مَنْ إِلَيْكَ دَعَانَا", "lt": "Yâ rabbanâ shalli wa sallim da’iman ۞ ‘alâ ḫabîbika man ilaika da’ânâ", "id": "Wahai Tuhan kami, limpahkanlah rahmat dan keselamatan selamanya pada kekasih-Mu yang telah menyeru kami kepada-Mu.", "no": 12},
{"ar": "اللَّهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ وَعَلَى آلِهِ", "lt": "{Allâhumma shalli wa sallim wa bârik ‘alaihi wa ‘ala âlihi}", "id": "Ya Allah limpahkanlah rahmat keagungan, keselamatan, serta keberkahan kepada Nabi dan keluarganya.", "no": 13}]},
{judul:"Bagian IV: Lamma dana waqtu…",isi:[
{"ar": "لَمَّا دَنَا وَقْتُ الْبُرُوزِ لِأَحْمَدِ ۞ عَنْ إِذْنِ مَنْ مَا شَاءَهُ قَدْ كَانَا", "lt": "Lammâ dânâ waqtul-burûzi li aḥmadin ۞ ‘an idzni man mâ syâ’ahu qad kânâ", "id": "Ketika telah dekat waktu kelahiran Ahmad ﷺ dari izin-Nya, yang apabila menghendaki sesuatu pasti terwujud.", "no": 1},
{"ar": "حَمَلَتْ بِهِ الْأُمُّ الْأَمِينَةُ بِنْتُ وَهْ ۞ ب مَنْ لَهَا أَعْلَى الْإِلَهُ مَكَانَا", "lt": "Ḥamalat bihil-ummul-amînatu bintu wah- ۞ bin man lahâ a‘lal-ilâhi makânâ", "id": "Ia ﷺ berada di dalam kandungan sang ibu Aminah binti Wahb, seseorang Allah muliakan kedudukannya.", "no": 2},
{"ar": "مِنْ وَالِدِ الْمُخْتَارِ عَبْدِ اللَّهِ بْنِ ۞ عَبْدِ لْمُطَّلِبِ رَأَى الْبُرْهَانَا", "lt": "Min wâlidil-mukhtâri ‘abdillâhib-ni ۞ ‘abdill-mutahallibin ra’al-burhânâ", "id": "Dari ayah sang hamba yang terpilih ﷺ, yaitu (ayahnya itu) Abdullah bin Abdul Muthalib yang melihat tanda-tanda (isyarat kenabian).", "no": 3},
{"ar": "قَدْ كَانَ يَغْمُرُ نُورُ طَهَ وَجْهَهُ ۞ وَسَرَى إِلَى الْإِبْنِ الْمَصُونِ عِيَانَا", "lt": "Qad kânâ yaghmuru nûru thaha wajhahu ۞ wa sarâ ilal-ibnil-mashûni ‘ayânâ", "id": "Wajah sang ayah semula diliputi terang cahaya Thâhâ ﷺ, yang kemudian cahaya itu berpindah kepada sang anak yang dijaga.", "no": 4},
{"ar": "وَهُوَ ابْنُ هَاشِمِ الْكَرِيمِ الشَّهْمِ بْنِ ۞ عَبْدِ مَنَافِ بْنِ قُصَيٍّ كَانَا", "lt": "Wa huwab-nu hâsyimil-karîmisy-syahamib-ni ۞ ‘abdi manâfib-ni qushayyin kânâ", "id": "Dia adalah keturunan Hasyim yang mulia dan perkasa, putra Abdu Manâf, keturunan qushay yang dahulu.", "no": 5},
{"ar": "وَالِدُهُ يُدْعَى حَكِيمًا شَأْنُهُ ۞ قَدِ اعْتَلَى أَعْزِزْ بِذَلِكَ شَانَا", "lt": "Wâliduhu yud‘â ḫakîman sya’nuhu ۞ qadi’-talâ a‘ziz bidzâlika syânâ", "id": "Ayahnya digelari hakim (orang yang adil). Kepribadiannya luhur. Muliakanlah (beliau) atas dasar kepribadian itu!", "no": 6},
{"ar": "وَاحْفَظْ أُصُولَ الْمُصْطَفَى حَتَّى تَرَى ۞ فِي سِلْسِلَاتِ أُصُولِهِ عَدْنَانَا", "lt": "Waḥfadh ushûlal-mushthafâ ḫatâ tarâ ۞ fî silsilâti ushûlihi ‘adnânâ", "id": "Hafalkanlah silsilah keturunan sang nabi terpilih ﷺ hingga kautemukan silsilahnya berakar pada (datuknya) Adnan.", "no": 7},
{"ar": "فَهُنَاكَ قِفْ وَاعْلَمْ بِرَفْعِهِ إِلَى إِسْ ۞ مَاعِيلَ كَانَ لِلْأَبِ مِعْوَانَا", "lt": "Fahunâka qif wa‘lam biraf‘ihi ilâ is- ۞ mâ’îla kânâ lil-abi mi‘wânâ", "id": "Bila silsilah telah sampai kepada Adnan, berhentilah! Ketahuilah bahwa nasabnya bersambung hingga Nabi Ismail as yang telah menjadi pendukung ayahnya (Ibrahim as).", "no": 8},
{"ar": "وَحِينَمَا حَمَلَتْ بِهِ أَمِينَةٌ ۞ لَمْ تَشْكُ شَيْئًا يَأْخُذُ النِّسْوَانَا", "lt": "Wa ḫinamâ ḫamalat bihi âminatun ۞ lam tasyku syai’an ya'khudzun-niswânâ", "id": "Kala mengandungnya, Sayyidah Aminah ra tidak mengeluh sebagaimana perempuan hamil pada umumnya.", "no": 9},
{"ar": "وَبِهَا أَحَاطَ اللَّطْفُ مِنْ رَبِّ السَّمَا ۞ أَقْصَى الْأَذَى وَالْهَمَّ وَالْأَحْزَانَا", "lt": "Wa bihâ aḥâthal-luthfu min rabbis-samâ ۞ aqshal-adzâ walhamma wal-aḥzânâ", "id": "Selubung kelembutan dari Allah pemelihara langit yang meliputi Sayyidah Aminah melenyapkan segala rasa sakit, kegelisahan, dan kesedihan.", "no": 10},
{"ar": "وَرَأَتْ كَمَا قَدْ جَاءَ مَا عَلِمْتَ بِهِ ۞ أَنَّ الْمُهَيْمِنَ شَرَّفَ الْأَكْوَانَا", "lt": "Wa ra'at kamâ qad jâ'a mâ’alimaat bihi ۞ annal-muhaimina syarrafal-akwânâ", "id": "Kemudian Sayyidah Aminah menyaksikan, sebagaimana telah tiba sesuatu yang diketahuinya, bahwa yang Maha Pemelihara telah memuliakan alam semesta.", "no": 11},
{"ar": "بِالطُّهْرِ مَنْ فِي بَطْنِهَا فَاسْتَبْشَرَتْ ۞ وَدَنَا الْمَخَاضُ فَأُتْرِعَتْ رِضْوَانَا", "lt": "Bith-thuhri man fî bathnihâ fastabsyarat ۞ wa danal-makhâdlu fa'utri'at ridlwânâ", "id": "Dengan kesucian bayi di dalam kandungannya, ia pun bergembira ketika telah dekat saat-saat kelahiran, hingga meluap-luaplah keridhaannya.", "no": 12},
{"ar": "(سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ × ٤ ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ فِي كُلِّ لَحْظَةٍ أَبَدًا عَدَدَ خَلْقِهِ وَرِضَاءَ نَفْسِهِ وَزِينَةَ عَرْشِهِ وَمِدَادَ كَلِمَاتِهِ)", "lt": "(Subḥânallâhi wal-ḥamdulillâhi wa lâ ilâha illallâhu wallâhu akbaru 4x, wa lâ ḫaula wa lâ quwwata illâ billâhil-‘aliyyil-‘adhîmi fî kulli laḥdhatin abadan ‘adada khalqihi wa ridlâ'a nafsihi wa zînata ‘arsyihi wa midâda kalimatihi)", "id": "[Membaca tasbih, tahmid, tahlil, takbir, 4x, lalu hauqalah]. (Mahasuci Allah, segala puji bagi Allah, tiada Tuhan selain Allah, Allah Mahabesar. Tiada daya dan upaya kecuali dengan pertolongan Allah yang Mahatinggi, lagi Mahaagung sebanyak bilangan ciptaannya, dan seluas keridhaannya, dan seberat timbangan arsynya dan juga sebanyak tinta yang digunakan untuk menulis kalimatnya).", "no": 13},
{"ar": "وَتَجَلَّتِ الْأَنْوَارُ مِنْ كُلِّ الْجِهَا ۞ تِ فَوَقْتُ مِيلَادِ الْمُشَفَّعِ حَانَا", "lt": "Wa tajallatil-anwâru min kullil-jihâ- ۞ ti fawaqtu mîlâdil-musyaffa‘i ḫânâ", "id": "Maka muncullah cahaya-cahaya dari segala penjuru dan detik kelahiran sosok yang diharapkan syafaatnya itu pun tiba.", "no": 14},
{"ar": "وَقُبَيْلَ فَجْرٍ أَبْرَزَتْ شَمْسُ الْهُدَى ۞ ظَهَرَ الْحَبِيبُ مُكَرَّمًا وَمُصَانَا", "lt": "Wa qubaila fajrin abrazat syamsal-hudâ ۞ dhaharal-ḥabîbu mukarraman wa mushânâ", "id": "Beberapa saat sebelum terbitnya fajar muncullah matahari hidayah, lahirlah sang kekasih yang dimuliakan dan dijaga.", "no": 15}]},
{judul:"Mahallul Qiyam",isi:[
{"ar": "مَحَلُّ الْقِيَامِ", "lt": "(mahalul-qiyâmi)", "id": "(Saatnya berdiri)", "no": 1},
{"ar": "صَلَّى اللَّهُ عَلَى مُحَمَّدْ ۞ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمْ ٣×", "lt": "Shallallâhu ‘alâ muḥammad ۞ shallallâhu ‘alaihi wa sallam 3x", "id": "Semoga Allah melimpahkan rahmat kepada (Nabi) Muhammad. Semoga Allah melimpahkan rahmat dan keselamatan kepada (Nabi) Muhammad.", "no": 2},
{"ar": "يَا نَبِي سَلَامٌ عَلَيْكَ ۞ يَا رَسُولْ سَلَامٌ عَلَيْكَ", "lt": "Yâ nabî salâmu ‘alaika ۞ yâ rasûl salâm ‘alaika", "id": "Wahai Nabi ﷺ keselamatan bagimu, wahai rasul keselamatan bagimu.", "no": 3},
{"ar": "يَا حَبِيب سَلَامٌ عَلَيْكَ ۞ صَلَوَاتُ اللَّهِ عَلَيْكَ", "lt": "Yâ ḫabîb salâm ‘alaika ۞ yâ rasûl salâm ‘alaika", "id": "Wahai kekasih keselamatan bagimu, shalawat Allah bagimu.", "no": 4},
{"ar": "أَبْرَزَ اللَّهُ الْمُشَفَّعْ ۞ صَاحِبَ الْقَدْرِ الْمُرَفَّعْ", "lt": "Abrazallâhul-musyaffa‘ ۞ shâhibal-qadril-muraffa‘", "id": "Allah telah mendatangkan (ke dunia) nabi yang diharapkan syafaat, yang memiliki derajat yang dimuliakan.", "no": 5},
{"ar": "فَمَلَا النُّوْرُ النَّوَاحِي ۞ عَمَّ كُلَّ الْكَوْنِ أَجْمَعْ", "lt": "Famalan-nûrun-nawâḥî ۞ ‘amma kullal-kauni ajma‘", "id": "Semburat cahaya memenuhi segala penjuru, meliputi seluruh alam semesta.", "no": 6},
{"ar": "نُكِّسَتْ أَصْنَامُ شِرْكٍ ۞ وَبِنَا الشِّرْكِ تَصَدَّعْ", "lt": "Nukkisat ashnâmu syirkin ۞ wa binasy-syirki tashadda‘", "id": "Patung-patung berhala di Ka'bah pun dijungkirkan, dan bangunan kemusyrikan pun retak.", "no": 7},
{"ar": "وَدَنَا وَقْتُ الْهِدَايَةِ ۞ وَحِمَى الْكُفْرِ تَزَعْزَعْ", "lt": "Wa danâ waqtul-hidâyah ۞ wa ḫimal-kufri taza‘za‘", "id": "Saat-saat datangnya petunjuk kian dekat, dan benteng kekafiran pun berguncang.", "no": 8},
{"ar": "مَرْحَبًا أَهْلًا وَسَهْلًا ۞ بِكَ يَا ذَا الْقَدْرِ الْأَرْفَعْ", "lt": "Marḥaban ahlan wa sahlan ۞ bika yâ dzal-qadril-arfa‘", "id": "Selamat datang, wahai sang pemilik derajat yang mulia.", "no": 9},
{"ar": "يَا إِمَامَ أَهْلِ الرِّسَالَةْ ۞ مَنْ بِهِ الْآفَاتُ تُدْفَعْ", "lt": "Yâ imâma ahlir-risâlah ۞ man bihil-afâtu tudfa‘", "id": "Wahai imam dan pemimpin para rasul, yang dengannya ﷺ bencana-bencana tertolakkan.", "no": 10},
{"ar": "أَنْتَ فِي الْحَشْرِ مَلَاذُ ۞ لَكَ كُلُّ الْخَلْقِ تَفْزَعْ", "lt": "Anta fil-ḫusyri malâdzun ۞ laka kullul-khalqi tafza‘", "id": "Engkaulah tempat perlindungan di hari Kiamat, kepadamu lah seluruh makhluk takut (tak mendapatkan syafaat).", "no": 11},
{"ar": "وَيُنَادَوْنَ تَرَى مَا ۞ قَدْ دَهَى مِنْ هَوْلِ أَفْظَعْ", "lt": "Wa yunâdûna tarâ mâ ۞ qad dahâ min haulin afdha‘", "id": "Kemudian mereka datang memanggil-manggal, ketika menyaksikan dahsyatnya kepanikan dan kegentingan.", "no": 12},
{"ar": "مَرْحَبًا يَا نُورَ عَيْنِي (مَرْحَبًا) ۞ مَرْحَبًا جَدَّ الْحُسَيْنِي (مَرْحَبًا)", "lt": "Marḥaban yâ nûra ‘aini (marḥaban) ۞ marḥaban jaddal-ḫusaini (marḥaban)", "id": "Selamat datang wahai cahaya mataku, selamat datang wahai kakek dari Sayyidina Husain.", "no": 13},
{"ar": "فَلَهَا أَنْتَ فَتَسْجُدْ ۞ وَتُنَادَى اشْفَعْ تُشَفَّعْ", "lt": "Falahâ anta fatasjud ۞ wa tunâdâsy-fa‘ tusyaffa‘", "id": "Untuk mereka engkau bersujud (kepada Allah). Mereka memanggil-manggil minta syafaat (pertolongan), engkau pun menolongnya.", "no": 14},
{"ar": "فَعَلَيْكَ اللَّهُ صَلَّى ۞ مَا بَدَا النُّوْرُ وَشَغْشَغْ", "lt": "Fa‘alaikallâhu shallâ ۞ mâ badan-nûru wa sya‘sya‘", "id": "Semoga limpahan rahmat dari Allah tercurah kepadamu, selama cahaya bersinar dan pancarannya menyebar ke mana-mana.", "no": 15},
{"ar": "وَبِكَ الرَّحْمَنِ نَسْأَلْ ۞ وَإِلَهُ الْعَرْشِ يَسْمَعْ", "lt": "Wa bikar-rahmâna nas'al ۞ wa ilâhul-‘arsy yasma‘", "id": "Melalui dirimu (wahai Nabi ﷺ), kami memohon pada Allah ar-Rahman, maka pencipta arsy mendengar doa kami.", "no": 16},
{"ar": "رَبِّ فَاعْفُ لِي ذُنُوبِي (يَا اللَّهُ) ۞ بِبَرْكَةِ الْهَادِي الْمُشَفَّعْ (يَا اللَّهُ)", "lt": "Rabbi faghfir lî dzunûbî (ya Allâh) ۞ bibarkatil-hâdil-musyaffa‘ (yâ Allâh)", "id": "Ya Allah, ampunilah dosa-dosaku melalui perantara keberkahan sang penuntun yang diharapkan syafaatnya ﷺ.", "no": 17},
{"ar": "يَا عَظِيمَ الْمَنِّ يَا رَبْ ۞ شَمْلَنَا بِالْمُصْطَفَى اجْمَعْ", "lt": "Yâ ‘adhîmal-manni yâ rab ۞ syamlanâ bil-mushthafaj-ma‘", "id": "Wahai Maha Pemberi anugerah wahai Rabb, kumpulkanlah golongan kami dengan al-Musthafa ﷺ (sang nabi terpilih).", "no": 18},
{"ar": "وَبِهِ فَانْظُرْ إِلَيْنَا ۞ وَاعْطِنَا بِهِ كُلَّ مَطْمَعْ", "lt": "Wa bihi fandhur ilainâ ۞ wa‘thinâ bihi kulla muth‘am", "id": "Berkat beliau ﷺ, pandangilah kami dengan kasih sayang-Mu dan kami berkat beliau ﷺ, berilah segala yang kami inginkan.", "no": 19},
{"ar": "وَاكْفِنَا كُلَّ الْبَلَايَا ۞ وَادْفَعِ الْآفَاتِ وَازْفَعْ", "lt": "Wakfinâ kullal-balâyâ ۞ wadfa‘il-afâti warfa‘", "id": "Hindarkanlah kami dari segala bencana, dan cegahlah segala kesengsaraan, dan angkatlah sejauh-jauhnya.", "no": 20},
{"ar": "(صَلَّى اللَّهُ عَلَى مُحَمَّدْ) ۞ (صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمْ)", "lt": "(shallallâhu ‘alâ muḥammad) ۞ (shallallâhu ‘alaihi wa sallam)", "id": "Semoga Allah melimpahkan rahmat kepada Nabi Muhammad ﷺ. Semoga Allah melimpahkan rahmat dan keselamatan kepada beliau ﷺ.", "no": 21},
{"ar": "وَاسْقِنَا يَا رَبِّ أَغِثْنَا ۞ بِحَيَا هَطَّالٍ يَهْمَعْ", "lt": "Wasqinâ yâ rabb aghitsnâ ۞ biḫayyan haththal yahma‘", "id": "Ya Rabb, siramilah kami (dengan rahmatmu). Tolonglah kami dengan kehidupan yang dicurahi lebatnya hujan kasih sayang-Mu.", "no": 22},
{"ar": "وَاخْتِمِ الْعُمْرَ بِحُسْنَى ۞ وَاحْسِنِ الْعُقْبَى وَمَرْجَعْ", "lt": "Wakhtimil-‘umra biḫusnâ ۞ waḥsinil-‘uqbâ wa marja‘", "id": "Akhirilah usia kami dengan husnul khatimah dan perbaguslah kehidupan akhirat dan saat kami kembali kepada-Mu.", "no": 23},
{"ar": "وَصَلَاةُ اللَّهِ تَغْشَى ۞ مَنْ لَهُ الْحُسْنُ تَجَمَّعْ", "lt": "Wa shalâtullâhi taghsyâ ۞ man lahul-ḫusnu tajamma‘", "id": "Semoga rahmat Allah menyelubungi orang yang memiliki segala kumpulan kebaikan dalam dirinya.", "no": 24},
{"ar": "أَحْمَدَ الطُّهْرَ وَآلَهْ ۞ وَالصَّحَابَةَ مَا السَّنَا شَعْ", "lt": "Aḥmadath-thuhra wa âlih ۞ wash-shahâbat mas-sanâ sya‘", "id": "Dialah Ahmad ﷺ yang suci. Begitu juga, semoga menyelubungi keluarganya serta para sahabatnya dengan rahmat yang selalu bercahaya terang benderang.", "no": 25},
{"ar": "اَللَّهُمَّ صَلِّّ وَسَلِّمْ وَبَارِكَ عَلَيْهِ وَعَلَى آلِهِ", "lt": "(Allâhumma shalli wa sallim wa bârik ‘alaihi wa ‘ala âlihi)", "id": "Ya Allah limpahkanlah rahmat keagungan, keselamatan, serta keberkahan kepada Nabi dan keluarganya.", "no": 26}]},
{judul:"Bagian V: Wulidal Habib…",isi:[
{"ar": "وُلِدَ الْحَبِيْبُ فَخَرَّ حَالًا سَاجِدًا ۞ لِلَّهِ مَنْ أَنْشَأَنَا وَبَرَانَا", "lt": "Wulidal-ḫabîbu fakharra ḫâlan sâjidan ۞ lillâhi man ansya'anâ wa barânâ", "id": "Ketika sang kekasih ﷺ lahir, beliau ﷺ tertunduk dalam kondisi bersujud kepada Allah yang telah menghhidupan serta menciptakan kita.", "no": 1},
{"ar": "وَرِعَايَةُ الْمَوْلَى تُحِيْطُ بِأَحْمَدَ ۞ فِي كُلِّ حِيْنٍ بَاطِنًا وَعِيَانَا", "lt": "Wa ri‘âyatul-maulâ tuḫithu bi aḥmada ۞ fî kulli ḫînin bâthinan wa ‘ayâna", "id": "Dan bimbingan sang pencipta selalu menaungi Ahmad ﷺ setiap waktu, secara tersembunyi dan terlihat kasat mata.", "no": 2},
{"ar": "قَدْ أَرْضَعَتْهُ الْأُمُّ ثُمَّ ثُوَيْبَةُ ۞ وَحَلِيْمَةٌ مَنْ سُعْدُهَا قَدْ بَانَا", "lt": "Qad ardla‘athul-ummu tsumma tsuwaibatun ۞ wa ḫalîmatun man su‘duhâ qad bânâ", "id": "Beliau ﷺ disusui oleh ibunya dan diteruskan oleh Tsuwaibah ra kemudian Halimah ra yang telah jelas kebahagiaannya.", "no": 3},
{"ar": "قَدْ بَشَّرَتْ ثُوَيْبَةُ سَيِّدَهَا ۞ أَبَا لَهَبٍ أَعْتَقَهَا فَرْحَانَا", "lt": "Qad basysyarat tsuwaibatun sayyidahâ ۞ abâ lahabin a‘taqahâ farḫânâ", "id": "Ketika Tsuwaibah menyampaikan berita kepada tuannya (tentang kelahiran Muhammad), Abu Lahab memerdekakannya sebagai tanda sukacita.", "no": 4},
{"ar": "لَمْ يَنْسَ خَالِقُنَا لَهُ فَرْحَتَهُ ۞ بِالْمُصْطَفَى وَبِذَا الْحَدِيْثِ أَتَانَا", "lt": "Lam yansa khâliqunâ lahu farḫatahu ۞ bil-mushthafâ wa bidzâl-ḫaditsu atânâ", "id": "Tidaklah Tuhan yang Maha Pencipta lupa atas kesukacitaannya (Abu Lahab) dengan kelahiran al-Musthafa ﷺ, sebagaimana tercantum dalam hadits (riwayat Abbas bin Abdul Muthalib ra, di Shahih Bukhari).", "no": 5},
{"ar": "أَنَّ الْعَذَابَ مُخَفَّفٌ فِي كُلِّ إِثْـ ۞ ـنَيْنِ لِفَرْحَتِهِ بِمَانِ وَافَانَا", "lt": "Annal-‘adzâba mukhaffafun fî kulli its- ۞ naini lifarḫatihi biman wâfanâ", "id": "Bahwa siksaan Abu Lahab diringankan pada setiap hari Senin lantaran kegembiraannya atas (kelahiran) orang yang telah menunaikan kewajibannya kepada kita.", "no": 6},
{"ar": "هَذَا مَعَ الْكُفْرِ فَكَيْفَ بِفَرْحَةٍ ۞ مِنْ ذِي فُؤَادٍ امْتَلَأَ إِيْمَانَا", "lt": "Hâdzâ ma‘al-kufri fakaifa bifarḫatin ۞ min dzî fu'âdin imtalâ îmânâ", "id": "Demikianlah rahmat Allah terhadap orang kafir. Tak terbayangkan (anugerah) ketika kegembiraan itu muncul dari seorang mukmin yang hatinya dipenuhi keimanan.", "no": 7},
{"ar": "وَرَأَتْ حَلِيْمَةُ مَا قَدْ رَأَتْ مِنْ بَرَكَاتِ ۞ مُحَمَّدٍ مَا حَيَّرَ الْأَذْهَانَا", "lt": "Wa ra'at ḫalîmatu mâ qad ra'at min barakâ- ۞ ti muḥammadin mâ ḫayyaral-adzhânâ", "id": "Halimah ra menyaksikan sedemikian banyak keberkahan Muhammad ﷺ yang mencengangkan pikiran.", "no": 8},
{"ar": "دَرَّ لَهُ الثَّدْيُ وَقَدْ كَانَ ابْنُهَا ۞ يَبِيْتُ يَبْكِي مُسْغَبًا جِيْعَانَا", "lt": "Darra lahuts-tsadyu wa qad kânab-nuhâ ۞ yabîtu yabkî musghaban jai‘ânâ", "id": "Di antaranya, air susu Halimah ra mengalir padahal sebelumnya anaknya sendiri pun pada malam hari menangis terus karena lapar (lantaran air susu Halimah tak keluar sama sekali sebab ia juga kelaparan).", "no": 9},
{"ar": "لَكِنَّهُ لَيْلَةَ أَنْ جَاءَ الْحَبِيْـ ۞ ـبُ بَاتَ مَوْفُوْرَ الرِّضَا شَبْعَانَا", "lt": "Lakinnahu lailata an jâ` al-ḫabî- ۞ bu bâta maufûrar-ridlâ syab‘ânâ", "id": "Akan tetapi malam itu, sejak kedatangan sang kekasih ﷺ, putra kandung Halimah ra tidur pulas dan kenyang (karena air susunya mengalir dengan derasnya).", "no": 10},
{"ar": "وَدَرَّتِ النَّاقَةُ أَلْبَانًا وَقَدْ ۞ سَمُنَتْ دُوَيْبَتُهَا فَكَانَ شَانَا", "lt": "Wa darratin-nâqatu albânan wa qad ۞ sanumat duwaibatuhâ fakâna syânâ", "id": "Dan mengalir pulalah air susu untanya, lalu binatang menjadi gemuk dan sehat.", "no": 11},
{"ar": "أَنْكَرَهُ رِفْقَتُهَا وَسَلَّمَتْ ۞ أَشْجَارُ أَحْجَارٍ عَلَى مَوْلَانَا", "lt": "Ankarahu rifqatuhâ wa sallamat ۞ asyjârun ahjârun ‘alâ maulânâ", "id": "Halifikasinya membingungkan teman-teman yang bersamanya (Halimah ra). Permohonan dan bebatuan pun memberi salam kepada pemimpin kita ﷺ.", "no": 12},
{"ar": "سُبْحَانَ مَنْ أَنْطَقَ أَشْجَارًا وَأَخْـ ۞ ـجَارًا تُحَيِّي الْمُصْطَفَى سُبْحَانَا", "lt": "Subḥâna man athlaqa asyjâran wa ah- ۞ jâran tuḫayyil-mushthafâ subḥâna", "id": "Mahasuci Allah yang telah membuat pepohonan dan bebatuan berbicara, sebagai penghormatan kepada sang terpilih ﷺ. Mahasucilah Dia ﷺ.", "no": 13},
{"ar": "يَا رَبَّنَا صَلِّ وَسَلَّمْ دَائِمَا ۞ عَلَى حَبِيْبِكَ مَنْ إِلَيْكَ دَعَانَا", "lt": "Ya rabbanaâ shalli wa sallim dâ`iman ۞ ‘alâ ḫabîbika man ilaika da‘ânâ", "id": "Wahai Tuhan kami, limpahkanlah rahmat dan keselamatan selamanya pada kekasih-Mu yang telah menyeru kami kepada-Mu.", "no": 14},
{"ar": "اَللَّهُمَّ صَلِّّ وَسَلِّمْ وَبَارِكَ عَلَيْهِ وَعَلَى آلِهِ", "lt": "(Allâhumma shalli wa sallim wa bârik ‘alaihi wa ‘ala âlihi)", "id": "Ya Allah limpahkanlah rahmat keagungan, keselamatan, serta keberkahan kepada Nabi dan keluarganya.", "no": 15}]},
{judul:"Bagian VI: Hadza wa qad nasya'a",isi:[
{"ar": "هَذَا وَقَدْ نَشَأَ الْحَبِيْبُ بِسِيْرَةٍ ۞ مَرْضِيَّةٍ وَمَا أَتَى عِصْيَانَا", "lt": "Hâdzâ wa qad nasya'al-ḫabîbu bisîratin ۞ mardliyyatin wa mâ atâ ‘ishyânâ", "id": "Sang kekasih ﷺ tumbuh dewasa dalam rentang sejarah yang penuh keridhaan. Tidaklah beliau ﷺ berbuat maksiat sama sekali.", "no": 1},
{"ar": "تَرْعَاهُ عَيْنُ اللَّهِ مَنْ أَدَبَهُ ۞ أَحْسَنَ تَأْدِيْبِ النَّبِيِّ إِحْسَانَا", "lt": "Tar‘âhu ‘ainullâhi man addabahu ۞ ahsana ta'dîban-nabiyyi ihsânâ", "id": "Nabi ﷺ hidup dalam bimbingan Allah yang telah mendidik budi pekerti beliau ﷺ dengan sebaik-baik budi pekerti kenabian.", "no": 2},
{"ar": "فَنَشَأَ صَدُوْقًا مُحْسِنًا ذَا عِفَّةٍ ۞ وَفُتُوَّةٍ وَأَمَانَةٍ مِعْوَانَا", "lt": "Fanasyâ shadûqan muhsinan dzâ ‘iffatin ۞ wa futuwwatin wa amânatin mi‘wânâ", "id": "Nabi ﷺ tumbuh sebagai pribadi yang amat jujur, gemar berbuat baik, mampu mengendalikan diri, dermawan, amanah, suka menolong.", "no": 3},
{"ar": "ذَا هِمَّةٍ وَشَجَاعَةٍ وَتَوَقُّرٍ ۞ وَمَكَارِمٍ لَا تَخْتَصِي حُسْبَانَا", "lt": "Dzâ himmatin wa syajâ‘atin wa tawaqqurin ۞ wa makârimin lâ tahtashî husbânâ", "id": "Pemilik semangat, keberanian, ketenangan, serta segala bentuk sifat mulia yang tak terhitung banyaknya.", "no": 4},
{"ar": "دُعِيَ الْأَمِيْنَ وَهُوَ فِي أَهْلِ السَّمَا ۞ نِعْمَ الْأَمِيْنَ لَهُ الْمُهَيْمِنُ صَانَا", "lt": "Du‘iyal-amînu wa huwa fî ahlis-samâ ۞ ni‘mal-amînu lahul-muhaiminu shânâ", "id": "Beliau ﷺ digelari \"al-amin\" (yang tidak pernah berbohong) dan bagi penduduk langit ia beliau adalah ni'mal amîn (sebaik-baik orang yang tidak pernah berbohong). Yang Maha Memelihara senantiasa melindunginya.", "no": 5},
{"ar": "ذَهَبَتْ بِهِ الْأُمُّ تَزُوْرُ أَبَاهُ فِي ۞ طَيْبَةَ إِذْ فِيْهَا الْحَمَامُ كَانَا", "lt": "Dzahabat bihil-ummu tazûru abâhu fî ۞ thaibata idz fîhâl-himâmu kânâ", "id": "Ibunda Nabi ﷺ membawanya berziarah ke makam ayah beliau ﷺ (Sayyid Abdullah) di Thaibah (Madinah) karena di sanalah sang ayah wafat.", "no": 6},
{"ar": "وَالْمُصْطَفَى فِي بَطْنِهَا وَقَدْ أَتَى ۞ عَلَيْهِ سِتٌّ مِنْ سِنِيْهِ الْآنَا", "lt": "Wal-mushthafâ fî bathnihâ wa qad atâ ۞ ‘alaihi sittun min sinîh-ânâ", "id": "Nabi pilihan (saat sang ayah beliau wafat) masih dalam kandungan ibunya. Beliau mendatangi pusara sang ayah ketika usianya enam tahun.", "no": 7},
{"ar": "وَقَدْ أَتَاهَا الْمَوْتُ حِيْنَ رُجُوْعِهَا ۞ فَحَبَابُهُ عَبْدُ الْمُطَّلِبِ حَنَانَا", "lt": "Wa qad atâhal-mautu hîna rujû‘ihâ ۞ fahâbâhu ‘abdul-muthallibi hanânâ", "id": "Sang ibunda wafat dalam perjalanan pulang. Beliau ﷺ pun diasuh oleh Abdul Muthalib dengan penuh kasih sayang.", "no": 8},
{"ar": "سَنَتَيْنِ وَافَاهُ الْحَمَامُ فَضَمَّهُ ۞ عَمُّونِ مَلَالَ الْعَطْفِ عَلَيْهِ جَنَانَا", "lt": "Sanataini wâfâhul-himâmu fadlammahu ۞ ‘ammun malal-‘uthfu ‘alaihi janânâ", "id": "Dua tahun kemudian Abdul Muthalib pun wafat. Beliau ﷺ lalu diasuh pamannya, Abu Thalib, dengan penuh kelembutan.", "no": 9},
{"ar": "خَطَبَتْهُ بِنْتُ خُوَيْلِدٍ فِي الْخَمْسِ وَالْـ ۞ ـعِشْرِيْنَ حَازَتْ بِالْمُشَفَّعِ شَانَا", "lt": "Khathabat hu bintu khuwailidin fil-khamsi wal- ۞ ‘isyrîna hâzat bil-musyaffa‘i syânâ", "id": "Beliau ﷺ dilamar oleh Sayyidah Khadijah binti Khuwailid saat beliau ﷺ berusia 25 tahun, karena ia (Khadijah) telah mendengar keajaiban-keajaiban pada diri sang pemberi syafaat ﷺ.", "no": 10},
{"ar": "قَدْ حَقَّقَ الْمَوْلَى لَهَا آمَالَهَا ۞ نَالَتْ سَلَامًا عَالِيًا وَمَكَانَا", "lt": "Qad haqqaqal-maulâ lahâ âmâlahâ ۞ nâlat salâman ‘âliyan wa makânâ", "id": "Allah mengabulkan cita-citanya. Ia (Khadijah ra) pun mendapatkan kesejahteraan dan martabat yang mulia.", "no": 11},
{"ar": "وَحَلَّ مُشْكِلَةً لِوَضْعِ الْحَجَرِ الْـ ۞ أَسْوَدِ فِي الْكَعْبَةِ حَيْثُ أَبَانَا", "lt": "Wa halla musykilatan liwad‘il-hajari al- ۞ aswadi fil-ka‘bati haitsu abânâ", "id": "Kemudian beliau ﷺ menyelesaikan masalah (persengketaan kelompok) terkait peletakan Hajar Aswad setelah renovasi Ka'bah.", "no": 12},
{"ar": "عَنْ سَعَةِ الْعَقْلِ وَوَقَّادِ الْحِجَا ۞ سُبْحَانَ مَنْ عَلَّمَهُ وَأَعَانَا", "lt": "‘an sa‘atal-‘aqli wa waqqâdil-hijâ ۞ subhâna man ‘allamahu wa a‘ânâ", "id": "(Beliau mengurai konflik itu) dengan kejenuisan dan akal yang cemerlang. Mahasuci Allah yang telah mengajarinya dan menaunginya ﷺ.", "no": 13},
{"ar": "يَا رَبَّنَا صَلِّ وَسَلَّمْ دَائِمَا ۞ عَلَى حَبِيْبِكَ مَنْ إِلَيْكَ دَعَانَا", "lt": "Yâ rabbanâ shalli wa sallim da'iman ۞ ‘alâ habîbika man ilaika da‘ânâ", "id": "Wahai Tuhan kami, limpahkanlah rahmat dan keselamatan selamanya, pada kekasih-Mu yang telah menyeru kami kepada-Mu.", "no": 14},
{"ar": "اَللَّهُمَّ صَلِّّ وَسَلِّمْ وَبَارِكَ عَلَيْهِ وَعَلَى آلِهِ", "lt": "(Allâhumma shalli wa sallim wa bârik ‘alaihi wa ‘ala âlihi)", "id": "Ya Allah limpahkanlah rahmat keagungan, keselamatan, serta keberkahan kepada Nabi dan keluarganya.", "no": 15}]},
{judul:"Bagian VII: Wa atahu jibrilu…",isi:[
{"ar": "وَأَتَاهُ جِبْرِيْلُ بِوَحْيِ اللَّهِ فِي ۞ غَارِ حِرَاءٍ يَعْبُدُ الرَّحْمَنَا", "lt": "Wa atâhu jibrîlu biwahyillâhi fî ۞ ghâri hirâ'i ya'budur-rahmânâ", "id": "Jibril as datang pada beliau ﷺ membawa wahyu Allah di gua Hira’ ketika beliau ﷺ beribadah kepada (Allah) ar-Rahman.", "no": 1},
{"ar": "وَضَمَّهُ الثَّلَاثَ ثُمَّ أَرْسَلَهُ ۞ اِقْرَأْ وَرَبُّكَ عَلَّمَ الْإِنْسَانَا", "lt": "Wa dlammahuts-tsalâtsa tumma arsalahu ۞ iqra wa rabbuka ‘allamal-insânâ", "id": "Jibril as memeluknya sebanyak tiga kali lalu melepaskannya, (dan berkata) bacalah demi Tuhanmu yang memberi ilmu pada manusia.", "no": 2},
{"ar": "فَدَعَا ثَلَاثًا فِي خَفَا فَأَتَاهُ أَنْ ۞ اِصْدَعْ بِمَا تُؤْمَرُ بِهِ إِعْلَانَا", "lt": "Fada‘â tsalâtsan fî khafâ fa'atâhu an ۞ ishda‘ bimâ tu'mar bihi i‘lânâ", "id": "Lalu beliau ﷺ berdakwah dengan sembunyi-sembunyi selama tiga tahun hingga datangnya instruksi dari Allah “Sampaikanlah terang-terangan segala yang diperintahkan kepadamu”.", "no": 3},
{"ar": "كَثُرَ الْأَذَى وَهُوَ الصَّبُوْرُ لِرَبِّهِ ۞ وَهُوَ الشَّكُوْرُ وَكَانَ لَا يَتَوانَى", "lt": "Katsural-adzâ wa huwash-shabûru lirabbihi ۞ wa huwasy-syakûru wa kânâ lâ yatawânâ", "id": "Datanglah bertubi-tubi berbagai gangguan. Namun, beliau ﷺ sangat sabar terhadap ketentuan Tuhannya, dan beliau ﷺ pandai bersyukur, dan tidak kendor dalam menjalankan misi dakwahnya.", "no": 4},
{"ar": "مَاتَتْ خَدِيْجَةُ وَأَبُوْ طَالِبٍ فِي الْـ ۞ خَمْسِيْنَ فَاشْتَدَّ الْأَذَى فُنُوْنَا", "lt": "Mâtat khadîjatu wa abû thâlibin fil- ۞ khamsîna fasyataddal-adzâ'u funûnâ", "id": "Kemudian wafatlah istrinya, Khadijah ra dan Abu Thalib (pamannya) ketika usia Nabi ﷺ genap 50 tahun. Sehingga semakin dahsyatlah gangguan yang beraneka ragam.", "no": 5},
{"ar": "وَأَتَى ثَقِيْفًا دَاعِيًا فَرَمَوْهُ بِالْـ ۞ أَحْجَارِ بَلْ أَغْرَوْا بِهِ الشِّبْيَانَا", "lt": "Wa atâ tsaqîfan dâ‘iyan foramouhu bil- ۞ ahjâri bal aghrau bihish-sibyânâ", "id": "Beliau ﷺ berkunjung ke (Bani) Tsaqifah (Tha'if) untuk berdakwah. Di sana beliau ﷺ dilempari batu, bahkan digoda oleh anak-anak kecil.", "no": 6},
{"ar": "مَلَكُ الْجِبَالِ أَتَى فَقَالَاتْ بِقُوهَا ۞ فَقَالَ لَا، بَلْ أَرْتَجِي الْعُقْبَانَا", "lt": "Malakul-jibâli atâ faqâlath-biquhâ ۞ faqâla lâ, bal artajil-‘uqbânâ", "id": "Datanglah malaikat penguasa gunung dan berkata: “Apakah kutimpakan (gunung Uhud) di atas mereka (Bani Tsaqifah)?” Beliau ﷺ berkata: Tidak! Bahkan aku berharap generasi mereka di kemudian hari (mendapat petunjuk).", "no": 7},
{"ar": "أَسْرَى بِهِ الْمَوْلَى وَصَلَّى خَلْفَهُ الرُّْ ۞ سُلُ وَشَاهَدَ بَرْزَخًا وَجِنَانَا", "lt": "Asrâ bihil-maulâ wa shalla khafahur-ru- ۞ slu wa syâhada barzakhan wa jinânâ", "id": "Lalu Sang Maha Pencipta memperjalankan beliau ﷺ (ke Masjidil Aqsha), lalu para rasul bermakmum di belakangnya, yang beliau ﷺ kemudian menyaksikan (alam) barzakh dan surga.", "no": 8},
{"ar": "عَرَجَ الْحَبِيْبُ إِلَى السَّمَاوَاتِ الْعُلَى ۞ وَالْعَرْشِ وَالْكُرْسِيِّ رَأَى مَوْلَانَا", "lt": "‘arajal-habîbu ilas-samâwâtil-‘ulâ ۞ wal-‘arsyi wal-kursiyyî ra'â maulânâ", "id": "Naiklah sang kekasih ﷺ menembus langit-langit tertinggi, al-Arsy, dan al-Kursi, lalu berjumpa dengan Sang Tuan kita.", "no": 9},
{"ar": "وَالْإِذْنُ بِالْهِجْرَةِ جَاءَ لِيَثْرِبٍ ۞ فَفِيهِ ازْدَهَى الْبَلَدُ الْكَرِيْمُ وَزَانَا", "lt": "Wal-idznu bil-hijrati jâ'a liyatsribin ۞ fabihiz-dahal-baladul-karîmu wa zânâ", "id": "Tibalah izin untuk hijrah ke Yatsrib (Madinah). Berkat Nabi ﷺ negeri itu bangkit dan menjadi indah.", "no": 10},
{"ar": "فَأَقَامَ عَشْرًا دَاعِيًا وَمُجَاهِدًا ۞ وَصَحَابُهُ كَانُوا لَهُ أَعْوَانَا", "lt": "Fa aqâma ‘asyran dâ‘iyan wa mujâhidan ۞ wa shâhâbuhu kânû lahu a‘wânâ", "id": "Nabi ﷺ pun bermukim di Madinah selama sepuluh tahun sebagai dai dan pejuang dengan dukungan para sahabatnya.", "no": 11},
{"ar": "لَا يَرْفَعُونَ إِذَا أَتَى أَصْوَاتَهُمْ ۞ بَلْ لَا يُحِدُّونَ الْبَصَرَ إِمْعَانَا", "lt": "Lâ yarfa‘ûna idzâ atâ ashwâtahum ۞ bal lâ yuhiddûnal-bashar im‘ânâ", "id": "Mereka (para sahabat) tidaklah meninggikan suara ketika di hadapan beliau ﷺ. Bahkan tak berani memandang beliau ﷺ.", "no": 12},
{"ar": "قَدْرًا وَتَعْظِيْمًا لِشَأْنِ مُحَمَّدٍ ۞ إِذْ قَدْ تَلَوْا فِي فَضْلِهِ قُرْآنَا", "lt": "Qadran wa ta‘dhîman lisya'ni muhammadin ۞ idz qad talau fî fadllihi qur'ânâ", "id": "(Sikap itu) sebagai penghormatan dan pengagungan terhadap keutamaan Nabi Muhammad ﷺ yang telah mereka baca dan temukan dalam Al-Qur'an.", "no": 13},
{"ar": "وَلَقَدْ رَأَوْا مِنْ خُلُقِهِ عَجَبًا وَكَمْ ۞ قَدْ شَاهَدُوا مَا حَيَّرَ الْأَذْهَانَا", "lt": "Wa laqad ra'aû min khuluqihi ‘ajaban wa kam ۞ qad syâhadû mâ hayyaral-adzhânâ", "id": "Sungguh mereka telah melihat sesuatu yang menakjubkan dari budi pekerti beliau dan banyak pula mereka menyaksikan hal yang sukar dijangkau akal pikiran (mukjizat).", "no": 14},
{"ar": "كَرَمًا وَعَفْوًا وَالسَّخَا وَتَوَاضُعًا ۞ وَالْجِذْعَ حَنَّ مَحَبَّةً وَحَنَانَا", "lt": "Karaman wa ‘afwan was-sakhâ wa tawâdlu‘an ۞ wal-jidz’a hanna mahabbatan wa hanânâ", "id": "(Mereka menyaksikan) kemurahnya, sifat pemaafnya, kedermawanannya, dan kerendahhatiannya—batang kurma pun menangis rindu karena cintanya terhadap Nabi ﷺ.", "no": 15},
{"ar": "وَالْمَاءُ مِنْ بَيْنِ الْأَصَابِعِ نَابِعًا ۞ وَالْجَيْشُ أَضْحَى شَارِبًا رَيَّانَا", "lt": "Wal-mâ'a min bainil-ashâbi‘i nâbi‘an ۞ wal-jaisya adhlhâ syâriban rayyânâ", "id": "(Mereka juga menyaksikan) air memancar dari sela-sela jarinya ﷺ, lalu pasukan (sahabat beliau ﷺ) meminumnya hingga hilanglah dahaga mereka semuanya.", "no": 16},
{"ar": "وَاللَّهِ قَدْ عَظُمَتْ مَعَاجِزُ أَحْمَدٍ ۞ رَفَعَ الْمُهَيْمِنُ لِلنَّبِيِّ مَكَانَا", "lt": "Wallâhi qad ‘adhumat ma‘âjizu ahmadin ۞ rafa‘al-muhaiminu lin-nabiyyi makânâ", "id": "Demi Allah, mukjizat-mukjizat Ahmad ﷺ itu mulia. Sang Maha Memelihara telah mengangkat Nabi ﷺ ke derajat yang setinggi-tingginya.", "no": 17},
{"ar": "وَلَقَدْ غَزَا سَبْعًا وَعِشْرِيْنَ مَعَ الصَّـ ۞ ـحْبِ رِجَالًا قَدْ مَشَوْا رُكْبَانَا", "lt": "Wa laqad ghazâ sab‘an wa isyrîna ma‘ash-sha- ۞ hbi rijâlan qad masyau rukbânâ", "id": "Beliau ﷺ telah berjihad selama hidupnya sebanyak 27 kali bersama para sahabatnya dengan berjalan kaki atau berkendara dalam kafilah.", "no": 18},
{"ar": "أَكْرِمْ بِهِ وَبِصَحْبِهِ وَبِتَابِعٍ ۞ يَا رَبِّ أَلْحِقْنَا بِهِمْ إِحْسَانَا", "lt": "Akrim bihi wa bishahbihi wa bitâbi‘in ۞ yâ rabbi al-hiqnâ bihim ihsânâ", "id": "Muliankanlah Nabi ﷺ, para sahabatnya, serta para tabi'in. Wahai Tuhan kami jadikan kami mengikuti jejak mereka dalam perbuatan baik.", "no": 19},
{"ar": "يَا رَبَّنَا صَلِّ وَسَلَّمْ دَائِمَا ۞ عَلَى حَبِيْبِكَ مَنْ إِلَيْكَ دَعَانَا", "lt": "Yâ rabbanâ shalli wa sallim da'iman ۞ ‘alâ habîbika man ilaika da‘ânâ", "id": "Wahai Tuhan kami, limpahkanlah rahmat dan keselamatan selamanya pada kekasih-Mu yang telah menyeru kami kepada-Mu.", "no": 20},
{"ar": "اَللَّهُمَّ صَلِّّ وَسَلِّمْ وَبَارِكَ عَلَيْهِ وَعَلَى آلِهِ", "lt": "(Allâhumma shalli wa sallim wa bârik ‘alaihi wa ‘ala âlihi)", "id": "Ya Allah limpahkanlah rahmat keagungan, keselamatan, serta keberkahan kepada Nabi dan keluarganya.", "no": 21}]},
{judul:"Doa (Ad-du'a)",isi:[
{"ar": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "lt": "Bismillâhirrahmânirrahîmi", "id": "Dengan menyebut nama Allah yang Maha Pengasih lagi Maha Penyayang.", "no": 1},
{"ar": "الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ، اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى سَيِّدِنَا مُحَمَّدٍ فِي الْأَوَّلِينَ، وَصَلِّ وَسَلِّمْ عَلَى سَيِّدِنَا مُحَمَّدٍ فِي الْآخِرِينَ، وَصَلِّ وَسَلِّمْ عَلَى سَيِّدِنَا مُحَمَّدٍ فِي النَّبِيِّينَ، وَصَلِّ وَسَلِّمْ عَلَى سَيِّدِنَا مُحَمَّدٍ فِي الْمُرْسَلِينَ، وَصَلِّ وَسَلِّمْ عَلَى سَيِّدِنَا مُحَمَّدٍ فِي الْمَلَإِ الْأَعْلَى إِلَى يَوْمِ الدِّينِ، وَصَلِّ وَسَلِّمْ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِهِ وَصَحْبِهِ أَجْمَعِينَ", "lt": "Al-ĥamdulillâhi rabbil-‘âlamîna, allâhumma shalli wa sallim ‘alâ sayyidinâ muĥammadin fil-awwalîna, wa shalli wa sallim ‘alâ sayyidinâ muĥammadin fil-âkhirîna, wa shalli wa sallim ‘alâ sayyidinâ muĥammadin fin-nabiyyîna, wa shalli wa sallim ‘alâ sayyidinâ muĥammadin fil-mursalîna, wa shalli wa sallim ‘alâ sayyidinâ muĥammadin fil-malâ’il-a‘lâ ilâ yaumid-dîni, wa shalli wa sallim ‘alâ sayyidinâ muĥammadin wa ‘alâ âlihi wa shahbihi ajma‘îna.", "id": "Segala puji bagi Allah Tuhan seluruh keberadaan. \"Ya Allah, limpahkanlah rahmat dan keselamatan kepada junjungan kami Nabi Muhammad bersama orang-orang permulaan, limpahkanlah rahmat dan keselamatan kepada junjungan kami Nabi Muhammad bersama orang-orang terakhir, dan limpahkanlah rahmat dan keselamatan kepada junjungan kami Nabi Muhammad bersama para nabi, limpahkanlah rahmat dan keselamatan kepada junjungan kami Nabi Muhammad bersama para rasul, serta limpahkanlah rahmat dan keselamatan kepada junjungan kami Nabi Muhammad bersama para nabi orang-orang yang memiliki kemuliaan sampai hari kiamat. Limpahkanlah rahmat dan keselamatan kepada junjungan kami Nabi Muhammad, keluarga, dan sahabatnya secara keseluruhan.", "no": 2},
{"ar": "وَلَقَدْ أَشَرْتُ لِنَعْتِ مِنْ أَوْصَافِهِ ۞ تُحْيِي الْقُلُوبَ تُهَيِّجُ الْأَشْجَانَا", "lt": "Wa laqad asyartu lina‘ti man aushâfuhu ۞ tuĥyil-qulûba tuhayyijul-asyjânâ", "id": "Telah kutunjukkan sifat-sifat Nabi yang menghidupkan hati, mengguncang aneka kegelisahan.", "no": 3},
{"ar": "وَاللَّهُ قَدْ أَثْنَى عَلَيْهِ فَمَا يُسَى ۞ وَالْقَوْلُ مِنَّا أَوْ يَكُونُ ثَنَايَا", "lt": "Wallâhu qad atsnâ ‘alaihi famâ yusâ ۞ wil-qaulu minnâ au yakûnu tsanayâ", "id": "Allah telah memuji Nabi Muhammad. Lantas apalah artinya pujian kita dan bagaimana (pujian kita ini) dinamakan pujian?", "no": 4},
{"ar": "كِنَّا حُبًّا فِي السَّرَائِرِ قَدْ دَعَا ۞ لِمَدِيحِ صفوَةِ رَبِّنَا وَهَدَانَا", "lt": "Kinna ĥubban fis-sarâ'iri qad da‘â ۞ limadîhi shafwati rabbinâ wa ĥadânâ", "id": "Akan tetapi cinta kasih dalam sanubari telah memanggil dan mendorong kita untuk memuji hamba pilihan Sang Pencipta kita.", "no": 5},
{"ar": "وَإِذِ امْتَرَجْنَا بِالْمَوَدَّةِ هَهُنَا ۞ نَرْفَعُ أَيْدِيَفَقْرِنَا وَرَجَانَا", "lt": "Wa idzim-tazajnâ bil-mawadati hahunâ ۞ narfa'u aidî faqrinâ wa rajânâ", "id": "Setelah kita berpadu dengan cinta (terhadap Nabi) maka di sinilah kita menengadahkan kedua tangan kefakiran kita untuk berdoa dengan penuh harap.", "no": 6},
{"ar": "لِلْوَاحِدِ الْأَحَدِ الْعَلِيِّ إِلَهِنَا ۞ مُتَوَسِّلِينَ بِمَنْ إِلَيْهِ دَعَانَا", "lt": "Lil-wâĥidil-aĥadil-‘aliyyi ilâhinâ ۞ mutawassilîna biman ilaihi da‘ânâ", "id": "Kepada Tuhan yang Mahatunggal, Maha Esa, lagi Mahamulia melalui perantaraan sosok yang telah menyeru kita kepada-Nya (Nabi Muhammad).", "no": 7},
{"ar": "مُخْتَارِهِ وَحَبِيبِهِ وَصَفِيِّهِ ۞ زَيْنِ الْوُجُودِ بِهِ الْإِلَهُ حَبَانَا", "lt": "Mukhtârihi wa ĥabîbihi wa shafiyhi ۞ zainil-wujûdi bihil-ilâhu ĥabânâ", "id": "Hamba-Nya yang terpilih, kekasih-Nya, hamba tersayangnya, dan sebaik-baik ciptaan di alam semesta yang lantaran beliau Allah memberkahi kita.", "no": 8},
{"ar": "يَا رَبَّنَا يَا رَبَّنَا يَا رَبَّنَا ۞ بِالْمُصْطَفَى اَقْبِلْنَا أَجِبْ دَعْوَانَا", "lt": "Yâ rabbanâ yâ rabbanâ yâ rabbanâ ۞ bil-mushthafâq-balnâ ajib da‘wânâ", "id": "Wahai Tuhan kami, wahai Tuhan kami, wahai Tuhan kami, demi nabi yang terpilih terimalah kami dan kabulkanlah doa kami.", "no": 9},
{"ar": "أَنْتَ لَنَا أَنْتَ لَنَا يَا ذُخْرَنَا ۞ فِي هَذِهِ الدُّنْيَا وَفِي أُخْرَانَا", "lt": "Anta lanâ anta lanâ yâ dukhranâ ۞ fî hâdzihid-dunyâ wa fî ukhrânâ", "id": "Hanya engkaulah harapan kami, hanya engkaulah harapan kami, wahai satu-satunya tempat memohon dan harapan di dunia dan di akhirat kami.", "no": 10},
{"ar": "أَصْلِحْ لَنَا الْأَحْوَالَ وَاغْفِرْ ذَنْبَنَا ۞ وَلَا تُؤَاخِذْ رَبِّ إِنْ أَخْطَآنَا", "lt": "Ashliĥ lanal-ahwâla waghfir dzanbanâ ۞ wa lâ tu'âkhidz rabbi in akhthânâ", "id": "Perbaikilah keadaan kami dan ampunilah dosa-dosa kami dan janganlah Engkau murkai kami apabila kami berbuat kesalahan.", "no": 11},
{"ar": "وَاسْلُكْ بِنَا فِي نَهْجِ طَهَ الْمُصْطَفَى ۞ ثَبِّتْ عَلَى قَدَمِ الْحَبِيبِ خُطَانَا", "lt": "Wasluk binâ fî nahji thahal-mushthafâ ۞ tsabbit ‘alâ qadamil-ĥabîbi khuthânâ", "id": "Tetapkanlah kami dalam jalan ajaran Thâha sang terpilih dan mantapkanlah langkah-langkah kami pada jalur yang telah dilalui oleh sang kekasih.", "no": 12},
{"ar": "أَرِنَا بِفَضْلِ مِنْكَ طَلْعَةَ أَحْمَدَ ۞ فِي بَهْجَةِ عَيْنِ الرِّضَا تَرْعَانَا", "lt": "Arinâ bifadlli minka thal‘ata aĥmadi ۞ fî bahjatin ‘ainur-ridlâ tar‘ânâ", "id": "Dengan anugerah-Mu, perlihatkanlah kami wajah Ahmad dalam keindahan yang menggembirakan. Pandangan penuh keridhaan selalu menaungi kami.", "no": 13},
{"ar": "وَارْبُطْ بِهِ فِي كُلِّ حَالٍ حَبْلَنَا ۞ وَحِبَالَ مَنْ وَدَّ وَمَنْ وَلَانَا", "lt": "Warbuth bihi fî kulli hâlin ĥablanâ ۞ wa ĥibâla man wadda wa man wâlânâ", "id": "Ikatlah kami selalu dengan beliau dalam segala gerak-gerik kami, dan juga orang-orang yang mencintai dan mendukung kami.", "no": 14},
{"ar": "وَالْمُحْسِنِينَ وَمَنْ أَجَابَ نِدَاءَنَا ۞ وَذَوِي الْحُقُوقِ وَطَالِبًا أَوْصَانَا", "lt": "Wal-muĥsinîna wa man ajâba nidâ'anâ ۞ wa dzawil-ĥuqûqi wa thâliban aushânâ", "id": "Demikian pula orang-orang yang beramal shalih, orang-orang yang mendengar dakwah kami, orang yang kami berutang budi pada mereka, dan orang-orang yang memohon nasihat dari kami.", "no": 15},
{"ar": "وَالْحَاضِرِينَ وَسَاعِيًا فِي جَمْعِنَا ۞ هَا نَحْنُ بَيْنَ يَدَيْكَ أَنْتَ تَرَانَا", "lt": "Wal-ĥâdlirîna wa sâ‘iyan fî jam‘inâ ۞ hâ naĥnu baina yadaika anta tarânâ", "id": "Juga atas para hadirin dan penyelenggara dalam perkumpulan kami. (Ya Allah) inilah kami di hadapan-Mu dan Engkau senantiasa melihat kami.", "no": 16},
{"ar": "وَلَقَدْ رَجَوْنَاكَ فَحَقِّقْ سُؤْلَنَا ۞ وَاسْمَعْ بِفَضْلِكَ يَا سَمِيعُ دُعَانَا", "lt": "Wa laqad rajaunâka fahaqqiq su'lanâ ۞ wasma‘ bifadllika yâ samî‘u du‘ânâ", "id": "Sungguh kami mengharapkan-Mu maka kabulkanlah permohonan kami dan dengan anugerah-Mu dengarlah doa kami, wahai Yang Maha Mendengar.", "no": 17},
{"ar": "وَانْشُرْ بِنَا سُنَّةَ طَهَ فِي بِقَا ۞ عِ الْأَرْضِ وَاقْمَعْ كُلَّ مَنْ عَادَانَا", "lt": "Wanshur binâ sunnata thaha fî biqâ- ‘il-ardli waqma‘ kulla man ‘âdânâ", "id": "Jadikan kami sebagai penolong sunnah Thâha di seluruh pelosok bumi, dan hancurkanlah semua yang memusuhi kami.", "no": 18},
{"ar": "وَانْظُرْ إِلَيْنَا وَاسْقِنَا كَأْسَ الْهَنَا ۞ وَاشْفِ وَعَافِ عَاجِلًا مَرْضَانَا", "lt": "Wandhur ilainâ wasqinâ ka'sal-hanâ ۞ wasyfi wa ‘âfi ‘âjilan mardlânâ", "id": "Pandanglah kami dengan kasih sayang-Mu dan berilah kami minuman dari cangkir-cangkir (kecintaan pada Nabi) dan segera sembuhkanlah penyakit kami.", "no": 19},
{"ar": "وَاقْضِ لَنَا الْحَاجَاتِ وَاحْسِنْ خَتْمَنَا ۞ عِنْدَ الْمَمَاتِ وَأَصْلِحَنَّ عُقْبَانَا", "lt": "Waqdli lanal-hâjâti waĥsin khatmanâ ۞ ‘indal-mamâti wa ashlihna ‘uqbanâ", "id": "Kabulkanlah hajat-hajat kami dan akhirilah hidup kami dengan kebaikan (husnul khatimah) dan jadikanlah kebaikan pula di hari kemudian.", "no": 20},
{"ar": "يَا رَبِّ وَاجْمَعْنَا وَأَحْبَابًا لَنَا ۞ فِي دَارِ الْفِرْدَوْسِ يَا رَجَوْانَا", "lt": "Yâ rabbi waj-ma‘nâ wa ahbâban lanâ ۞ fî dârik-firdausi yâ rajwânâ", "id": "Wahai Tuhan, kumpulkanlah kami bersama kekasih-kekasih kami di surga firdaus-Mu, wahai satu-satunya harapan kami (Allah).", "no": 21},
{"ar": "بِالْمُصْطَفَى صَلَّ عَلَيْهِ وَآلِهِ ۞ مَا حَرَّكَتْ رِيحُ الصَّبَا أَغْصَانَا", "lt": "Bil-mushthafâ shalli ‘alaihi wa âlihi ۞ mâ harrakat rîĥush-shabâ aghshânâ", "id": "Demi hamba terpilih, limpahkanlah rahmat kepada Nabi dan keluarganya sebanyak semilir angin pagi yang menggerak-gerakkan dahan pepohonan.", "no": 22},
{"ar": "سُبْحَانَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُونَ، وَسَلَامٌ عَلَى الْمُرْسَلِينَ، وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "lt": "Subhâana rabbika rabbil-‘izzati ‘ammâ yashifûna, wa salâmun ‘alal-mursalîna, wal-ĥamdulillâhi rabbil-‘âlamîna.", "id": "Mahasuci Tuhanmu yang Maha Memiliki kekuasaan, dari apa yang mereka sifatkan. Semoga keselamatan tercurah kepada para rasul. Segala puji bagi Allah pemilik seluruh keberadaan.", "no": 23}]}]});
